x;height:300px;top:80px;left:50%;transform:translateX(-50%);background:rgba(255,255,255,.62)}.stage:after{width:240px;height:240px;top:111px;left:50%;transform:translateX(-50%);border:1px solid rgba(240,202,214,.34)}.stage-caption{position:absolute;top:20px;left:0;right:0;text-align:center;color:#c59aaa;letter-spacing:2px;font-size:9px;font-weight:800;z-index:3}.caption-dot{display:inline-block;width:4px;height:4px;border-radius:50%;background:#eda2b8;vertical-align:middle;margin:0 8px}.stage-sticker{position:absolute;z-index:3;color:#e9a0b7}.sticker-left{top:72px;left:40px;font-size:25px;transform:rotate(-13deg)}.sticker-right{right:44px;top:135px;font-size:26px;transform:rotate(13deg)}.avatar-wrap{position:absolute;z-index:2;inset:30px 0 7px;display:flex;align-items:center;justify-content:center}.avatar-wrap svg{height:100%;max-width:100%;filter:drop-shadow(0 9px 5px rgba(185,142,148,.1));overflow:visible}.stage-floor{position:absolute;bottom:40px;left:50%;width:180px;height:18px;transform:translateX(-50%);border-radius:50%;background:#e8cfd0;opacity:.5}.mood-tag{position:absolute;bottom:19px;right:20px;z-index:4;font-size:10px;font-weight:700;color:#be98a7;background:#fff8f8;border-radius:14px;padding:7px 11px}.mood-tag span{color:#d8b8e4;font-size:14px;margin-right:3px}.name-card{margin-top:13px;background:#fff;border:1px solid var(--line);border-radius:15px;height:62px;display:flex;align-items:center;padding:0 16px;gap:12px;box-shadow:0 5px 16px #b88e9c0c}.name-icon{width:34px;height:34px;border-radius:12px;background:#fff0f3;color:#e78ea9;display:grid;place-items:center;font-size:19px}.name-card label{display:flex;flex-direction:column;flex:1;gap:1px}.mini-label{font-size:8px;letter-spacing:1.1px;font-weight:800;color:#beaab8}.name-card input{border:0;outline:0;background:transparent;color:#665669;font-family:'Nunito',sans-serif;font-size:15px;font-weight:800;padding:0;width:100%}.edit-hint{font-size:14px;color:#cdb9c9}.preview-actions{display:flex;gap:10px;margin-top:12px}.preview-actions button{height:44px;border-radius:13px;cursor:pointer;font:700 12px 'DM Sans',sans-serif;transition:transform .16s,box-shadow .16s}.preview-actions button:hover{transform:translateY(-2px);box-shadow:0 7px 14px #c38ba326}.primary-button{background:#e98eaa;color:white;border:1px solid #e98eaa;flex:1;box-shadow:0 5px 12px #e98eaa30}.primary-button span{font-size:16px;margin-right:5px}.secondary-button{padding:0 17px;background:#fff;color:#987f99;border:1px solid var(--line)}.secondary-button span{font-size:15px;margin-right:5px}.wardrobe{border-radius:23px;background:#fff;border:1px solid #f2e7eb;box-shadow:var(--shadow);padding:24px 23px 16px;min-height:675px}.wardrobe-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:17px}.wardrobe-head h2{font-size:23px}.tiny-star{color:#e5a1b8;font-size:16px}.item-count{font-size:10px;font-weight:800;letter-spacing:.7px;color:#c6aebe;padding-bottom:4px}.category-tabs{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;padding:5px;background:#fbf6f7;border-radius:14px}.category-tab{height:52px;border:0;border-radius:10px;background:transparent;color:#aa9aaa;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font:600 9px 'DM Sans',sans-serif;transition:.16s}.category-tab .tab-icon{font-size:17px;line-height:18px}.category-tab.active{background:#fff;box-shadow:0 2px 8px #a8849d17;color:#d97f9e}.category-tab:hover:not(.active){color:#846e8b}.category-title{display:flex;align-items:center;justify-content:space-between;margin:18px 2px 11px}.category-title>div{display:flex;align-items:center;gap:8px}.category-emoji{width:25px;height:25px;border-radius:8px;background:#fff0f3;display:grid;place-items:center;color:#db88a3;font-size:15px}.category-title h3,.color-heading h3{margin:0;color:#68566a;font:800 13px 'Nunito',sans-serif}.options-count{font-size:10px;color:#b8a6b6}.item-grid{display:grid;grid-template-columns:repeat(6,