ansparent;padding:0;cursor:pointer;border-radius:50%;overflow:hidden}.custom-color-row input::-webkit-color-swatch-wrapper{padding:0}.custom-color-row input::-webkit-color-swatch{border:2px solid #fff;border-radius:50%;box-shadow:0 0 0 1px #eadde5}.color-tip{font-size:9px;color:#b69fb1;margin:7px 0 0}.color-tip span{color:#e8a4b9;margin-right:4px}.closet-strip{border-top:1px solid #f3e9ed;margin-top:15px;padding-top:12px;display:flex;align-items:center;justify-content:space-between;min-height:49px}.closet-copy{display:flex;align-items:center;gap:9px}.closet-icon{width:30px;height:30px;border-radius:10px;background:#f7f0fb;color:#b495cb;display:grid;place-items:center;font-size:16px}.closet-copy strong{display:block;font:800 11px 'Nunito',sans-serif;color:#705d75}.closet-copy small{display:block;font-size:8px;color:#b2a1b2;margin-top:2px}.saved-looks{display:flex;gap:6px}.saved-look{border:1px solid #f0e1e9;background:#fff9fb;color:#d588a4;border-radius:8px;width:31px;height:31px;cursor:pointer;font-size:15px}.saved-look:hover{background:#fff0f4}.empty-saved{font-size:9px;color:#beafbb;padding-right:3px}footer{height:48px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(234,216,222,.68);color:#b09daa;font-size:10px}footer b{color:#e596ad}.footer-right{font-size:8px;font-weight:800;letter-spacing:1px;color:#c0aebc}.footer-right i{font-style:normal;color:#e6a3b6;margin:0 6px}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);background:#655366;color:white;border-radius:12px;padding:11px 18px;font-size:12px;font-weight:600;box-shadow:0 7px 22px #59465e33;opacity:0;pointer-events:none;transition:.25s;z-index:20}.toast.show{opacity:1;transform:translate(-50%,0)}
