function currentCategory(){return categories.find(c=>c.id===active)}
function currentItem(catId=active){const c=categories.find(x=>x.id===catId);return c.items.find(i=>i[0]===state[catId])||c.items[0]}
function currentColor(id){return colors[id]||currentItem(id)[3]}
function renderTabs(){const root=$('#categoryTabs');root.innerHTML=categories.map(c=>`<button role="tab" aria-selected="${c.id===active}" class="category-tab ${c.id===active?'active':''}" data-cat="${c.id}"><span class="tab-icon">${c.icon}</span><span>${c.short}</span></button>`).join('');root.querySelectorAll('button').forEach(b=>b.onclick=()=>{active=b.dataset.cat;render()})}
function renderItems(){const c=currentCategory();$('#categoryName').textContent=c.label;$('#categoryEmoji').textContent=c.emoji;$('#optionsCount').textContent=`${c.items.length} estilos`;
 $('#itemGrid').innerHTML=c.items.map((it,i)=>`<button class="item-card ${state[active]===it[0]?'selected':''}" data-item="${it[0]}" aria-label="${esc(it[1])}" title="${esc(it[1])}"><span class="item-check">✓</span><span class="item-art" style="color:${it[3]}">${it[2]}</span><span class="item-label">${esc(it[1])}</span></button>`).join('');
 $('#itemGrid').querySelectorAll('button').forEach(b=>b.onclick=()=>{state[active]=b.dataset.item;delete colors[active];render()});$('#itemCount').textContent=`${String(categories.findIndex(x=>x.id===active)+1).padStart(2,'0')} / ${String(categories.length).padStart(2,'0')}`;renderColors()}
